/// <summary>
/// Update Source Table Arrival Date Time on modification of Temporary Table record
/// </summary>
public void modified()
{
    FormDataObject          formDataObject = any2Object(this) as FormDataObject;
    FormDataSource          formDataSource = formDataObject.datasource();

    WMSArrivalOverviewTmp   wmsArrivalOverviewTmp = formDataSource.cursor();

    PurchTable                  purchTable;
    METPurchTable               metPurchTable;
    InventTransferTable         inventTransferTable;
    METInventTransferTableExt   metInventTransferTableExt;

    next modified();

    if (wmsArrivalOverviewTmp.InventTransRefId)
    {
        switch (wmsArrivalOverviewTmp.InventTransType)
        {
            // CASE 1: Purchase Order
            case InventTransType::Purch: 
                purchTable = PurchTable::find(wmsArrivalOverviewTmp.InventTransRefId);

                if (purchTable)
                {
                    ttsbegin;
                    // Find the custom table record for update
                    metPurchTable = METPurchTable::find(purchTable.PurchId, true);

                    if (metPurchTable)
                    {
                        metPurchTable.ArrivalDateTime = wmsArrivalOverviewTmp.METArrivalDateTime;
                        metPurchTable.doUpdate(); 
                    }
                    ttscommit;
                }
                break;

            // CASE 2: Transfer Order
            case InventTransType::TransferOrderReceive:
                inventTransferTable = InventTransferTable::find(wmsArrivalOverviewTmp.InventTransRefId);

                if (inventTransferTable)
                {
                    ttsbegin;
                    metInventTransferTableExt = METInventTransferTableExt::findByTransferId(inventTransferTable.TransferId, true);

                    if (metInventTransferTableExt)
                    {
                        metInventTransferTableExt.ArrivalDateTime = wmsArrivalOverviewTmp.METArrivalDateTime;
                        metInventTransferTableExt.doUpdate(); 
                    }
                    ttscommit;
                }
                break;
        }
    }
}
